// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpValue) public {
        vm.assume(warpValue > 0 && warpValue <= block.timestamp + 1000000);
        vm.warp(warpValue);
        uint256 initialTimestamp = block.timestamp;
        uint256 initialPastBlockTime = c.pastBlockTime();

        // Ensure the call will succeed: block.timestamp > pastBlockTime and value is exactly 10 ether
        vm.assume(initialTimestamp > initialPastBlockTime);

        // Perform the fallback call with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            // After a successful fallback, pastBlockTime should equal the block timestamp of that call
            assertTrue(c.pastBlockTime() == block.timestamp, "pastBlockTime should equal block.timestamp after successful fallback");
        } else {
            // If it reverted, pastBlockTime should remain unchanged
            assertTrue(c.pastBlockTime() == initialPastBlockTime, "pastBlockTime should remain unchanged if call reverted");
        }
    }
}

